test.describe('persistence and duplicates', () => {
  test('stored data preserves trimmed username and lowercased email, excludes passwords', async ({ page }) => {
    await resetRegistration(page);
    const { username: rawUsername, email: rawEmail } = uniqueRegistration();
    const paddedUsername = '  ' + rawUsername + '  ';
    const mixedCaseEmail = rawEmail.replace('@', '@').split('').map((ch, i) => i % 2 === 0 ? ch.toUpperCase() : ch.toLowerCase()).join('');
    const pw = 'Password01';
    await fillRegistration(page, { username: paddedUsername, email: mixedCaseEmail, password: pw });
    await submitRegistration(page);
    await expect(successFeedback(page)).toBeVisible();
    const corpus = await storageCorpus(page);
    const allValues = Object.values(corpus).join(' ');
    expect(allValues).toContain(rawUsername);
    expect(allValues).not.toContain(paddedUsername);
    expect(allValues).toContain(rawEmail.toLowerCase());
    expect(allValues).not.toContain(mixedCaseEmail);
    expect(allValues).not.toContain(pw);
    const allKeys = Object.keys(corpus).join(' ').toLowerCase();
    expect(allKeys).not.toMatch(/password/);
  });

  test('duplicate username and email rejected after reload', async ({ page }) => {
    await resetRegistration(page);
    const { username, email } = uniqueRegistration();
    const pw = 'Password01';
    await fillRegistration(page, { username, email, password: pw });
    await submitRegistration(page);
    await expect(successFeedback(page)).toBeVisible();
    await page.reload();
    const c = controls(page);
    await fillRegistration(page, { username: username.toUpperCase(), email: email.toUpperCase(), password: pw });
    await c.submit.click();
    await expectRejection(page);
    await expectFieldError(page, 'username');
    await expectFieldError(page, 'email');
  });

  test('rejected attempt reserves nothing', async ({ page }) => {
    await resetRegistration(page);
    const { username, email } = uniqueRegistration();
    const shortPw = 'Short1';
    await fillRegistration(page, { username, email, password: shortPw });
    await submitRegistration(page);
    await expectRejection(page);
    await fillRegistration(page, { username, email, password: 'Password01' });
    await submitRegistration(page);
    await expect(successFeedback(page)).toBeVisible();
  });
});

